#include "tensorrt_backend.hpp"
#include <NvInfer.h>
#include <cuda_runtime.h>
#include <nppcore.h>
#include <nppi_geometry_transforms.h>
#include <fstream>
#include <iostream>
#include <memory>
#include <stdexcept>
#include <utility>
namespace lesson21 { namespace {
void check_cuda(cudaError_t e,const char* op){if(e!=cudaSuccess)throw std::runtime_error(std::string(op)+": "+cudaGetErrorString(e));}
void check_npp(NppStatus e,const char* op){if(e!=NPP_SUCCESS)throw std::runtime_error(std::string(op)+" NPP status "+std::to_string((int)e));}
class Logger final:public nvinfer1::ILogger{void log(Severity s,const char*m) noexcept override{if(s<=Severity::kWARNING)std::cerr<<"[TensorRT] "<<m<<'\n';}};
std::vector<char> read_engine(const std::string&p){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f||f.tellg()<=0)throw std::runtime_error("cannot open engine: "+p);std::vector<char>b((size_t)f.tellg());f.seekg(0);if(!f.read(b.data(),(std::streamsize)b.size()))throw std::runtime_error("cannot read engine");return b;}
NppStreamContext npp_context(cudaStream_t stream){NppStreamContext c{};cudaDeviceProp p{};check_cuda(cudaGetDevice(&c.nCudaDeviceId),"cudaGetDevice");check_cuda(cudaGetDeviceProperties(&p,c.nCudaDeviceId),"cudaGetDeviceProperties");c.hStream=stream;c.nMultiProcessorCount=p.multiProcessorCount;c.nMaxThreadsPerMultiProcessor=p.maxThreadsPerMultiProcessor;c.nMaxThreadsPerBlock=p.maxThreadsPerBlock;c.nSharedMemPerBlock=p.sharedMemPerBlock;c.nCudaDevAttrComputeCapabilityMajor=p.major;c.nCudaDevAttrComputeCapabilityMinor=p.minor;check_cuda(cudaStreamGetFlags(stream,&c.nStreamFlags),"cudaStreamGetFlags");return c;}
__global__ void normalize(const unsigned char*src,float*dst,int w,int h,int batch){int x=blockIdx.x*blockDim.x+threadIdx.x,y=blockIdx.y*blockDim.y+threadIdx.y;if(x>=w||y>=h)return;size_t q=((size_t)y*w+x)*3,plane=(size_t)w*h,base=(size_t)batch*3*plane,at=(size_t)y*w+x;dst[base+at]=src[q+2]/255.f;dst[base+plane+at]=src[q+1]/255.f;dst[base+2*plane+at]=src[q]/255.f;}
struct Slot{cudaStream_t stream{};cudaEvent_t done{},p0{},p1{},i0{},i1{},d0{},d1{};NppStreamContext npp{};std::unique_ptr<nvinfer1::IExecutionContext> context;void* input{};void* output{};size_t input_capacity{},output_capacity{};std::vector<void*> temporaries;BatchMetadata metadata;std::vector<float> host_output;};
}
struct TensorRtBackend::Impl {
 Logger logger;std::unique_ptr<nvinfer1::IRuntime> runtime;std::unique_ptr<nvinfer1::ICudaEngine> engine;std::string input_name,output_name;cv::Size input_size;std::vector<Slot> slots;
 Impl(const std::string&path,size_t count,cv::Size size):input_size(size){if(count==0||size.width<=0||size.height<=0)throw std::invalid_argument("invalid backend capacity");auto bytes=read_engine(path);runtime.reset(nvinfer1::createInferRuntime(logger));if(!runtime)throw std::runtime_error("create runtime failed");engine.reset(runtime->deserializeCudaEngine(bytes.data(),bytes.size()));if(!engine)throw std::runtime_error("deserialize engine failed");for(int i=0;i<engine->getNbIOTensors();++i){const char*n=engine->getIOTensorName(i);if(engine->getTensorIOMode(n)==nvinfer1::TensorIOMode::kINPUT)input_name=n;else output_name=n;}if(input_name.empty()||output_name.empty())throw std::runtime_error("expected one input and output");slots.reserve(count);for(size_t k=0;k<count;++k){Slot s;check_cuda(cudaStreamCreate(&s.stream),"create stream");for(auto*e:{&s.done,&s.p0,&s.p1,&s.i0,&s.i1,&s.d0,&s.d1})check_cuda(cudaEventCreate(e),"create event");s.npp=npp_context(s.stream);s.context.reset(engine->createExecutionContext());if(!s.context)throw std::runtime_error("create context failed");slots.push_back(std::move(s));}}
 ~Impl(){for(auto&s:slots){if(s.stream)cudaStreamSynchronize(s.stream);for(void*p:s.temporaries)cudaFree(p);if(s.input)cudaFree(s.input);if(s.output)cudaFree(s.output);for(auto e:{s.done,s.p0,s.p1,s.i0,s.i1,s.d0,s.d1})if(e)cudaEventDestroy(e);if(s.stream)cudaStreamDestroy(s.stream);}}
 void submit(size_t index,const std::vector<cv::Mat>&images,BatchMetadata metadata){if(index>=slots.size()||images.empty()||images.size()>4||metadata.frames.size()!=images.size())throw std::invalid_argument("invalid slot, batch, or metadata");Slot&s=slots[index];for(void*p:s.temporaries)check_cuda(cudaFree(p),"free previous temporary");s.temporaries.clear();nvinfer1::Dims4 shape((int)images.size(),3,input_size.height,input_size.width);if(!s.context->setInputShape(input_name.c_str(),shape))throw std::invalid_argument("batch outside engine profile");auto out_shape=s.context->getTensorShape(output_name.c_str());size_t output_elements=1;for(int i=0;i<out_shape.nbDims;++i){if(out_shape.d[i]<0)throw std::runtime_error("unresolved output shape");output_elements*=out_shape.d[i];}size_t input_elements=images.size()*3ull*input_size.area();if(s.input_capacity<input_elements*sizeof(float)){if(s.input)check_cuda(cudaFree(s.input),"free input");check_cuda(cudaMalloc(&s.input,input_elements*sizeof(float)),"allocate input");s.input_capacity=input_elements*sizeof(float);}if(s.output_capacity<output_elements*sizeof(float)){if(s.output)check_cuda(cudaFree(s.output),"free output");check_cuda(cudaMalloc(&s.output,output_elements*sizeof(float)),"allocate output");s.output_capacity=output_elements*sizeof(float);}s.host_output.resize(output_elements);s.metadata=std::move(metadata);check_cuda(cudaEventRecord(s.p0,s.stream),"preprocess start");for(size_t j=0;j<images.size();++j){const cv::Mat&image=images[j];if(image.empty()||image.type()!=CV_8UC3||!image.isContinuous())throw std::invalid_argument("input must be continuous CV_8UC3");void*source{};void*resized{};check_cuda(cudaMalloc(&source,image.total()*3),"allocate source");check_cuda(cudaMalloc(&resized,(size_t)input_size.area()*3),"allocate resize");s.temporaries.push_back(source);s.temporaries.push_back(resized);check_cuda(cudaMemcpyAsync(source,image.data,image.total()*3,cudaMemcpyHostToDevice,s.stream),"upload source");check_npp(nppiResize_8u_C3R_Ctx((Npp8u*)source,image.cols*3,{image.cols,image.rows},{0,0,image.cols,image.rows},(Npp8u*)resized,input_size.width*3,{input_size.width,input_size.height},{0,0,input_size.width,input_size.height},NPPI_INTER_LINEAR,s.npp),"NPP resize");normalize<<<dim3((input_size.width+15)/16,(input_size.height+15)/16),dim3(16,16),0,s.stream>>>((unsigned char*)resized,(float*)s.input,input_size.width,input_size.height,(int)j);check_cuda(cudaGetLastError(),"normalize launch");}check_cuda(cudaEventRecord(s.p1,s.stream),"preprocess end");if(!s.context->setTensorAddress(input_name.c_str(),s.input)||!s.context->setTensorAddress(output_name.c_str(),s.output))throw std::runtime_error("bind tensors failed");check_cuda(cudaEventRecord(s.i0,s.stream),"inference start");if(!s.context->enqueueV3(s.stream))throw std::runtime_error("enqueueV3 failed");check_cuda(cudaEventRecord(s.i1,s.stream),"inference end");check_cuda(cudaEventRecord(s.d0,s.stream),"download start");check_cuda(cudaMemcpyAsync(s.host_output.data(),s.output,output_elements*sizeof(float),cudaMemcpyDeviceToHost,s.stream),"download output");check_cuda(cudaEventRecord(s.d1,s.stream),"download end");check_cuda(cudaEventRecord(s.done,s.stream),"completion event");}
 bool ready(size_t i)const{if(i>=slots.size())throw std::out_of_range("slot");auto e=cudaEventQuery(slots[i].done);if(e==cudaErrorNotReady)return false;check_cuda(e,"query completion");return true;}
 GpuBatchResult collect(size_t i){Slot&s=slots.at(i);check_cuda(cudaEventSynchronize(s.done),"wait completion");GpuBatchResult r{s.metadata,std::move(s.host_output),{},0,0,0};auto d=s.context->getTensorShape(output_name.c_str());for(int j=0;j<d.nbDims;++j)r.output_shape.push_back(d.d[j]);check_cuda(cudaEventElapsedTime(&r.preprocess_ms,s.p0,s.p1),"preprocess time");check_cuda(cudaEventElapsedTime(&r.inference_ms,s.i0,s.i1),"inference time");check_cuda(cudaEventElapsedTime(&r.d2h_ms,s.d0,s.d1),"download time");return r;}
};
TensorRtBackend::TensorRtBackend(const std::string&e,size_t n,cv::Size s):impl_(std::make_unique<Impl>(e,n,s)){}TensorRtBackend::~TensorRtBackend()=default;void TensorRtBackend::submit(size_t s,const std::vector<cv::Mat>&i,BatchMetadata m){impl_->submit(s,i,std::move(m));}bool TensorRtBackend::ready(size_t s)const{return impl_->ready(s);}GpuBatchResult TensorRtBackend::collect(size_t s){return impl_->collect(s);}
}
